using System.Drawing;
using System.Runtime.InteropServices;
using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyControl : UserControl
{
    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    private StatusStrip _statusStrip;

    public MyControl()
    {
        _statusStrip = new StatusStrip();
        // .NET 9 breaking change: StatusStrip no longer defaults to System render mode.
        // Explicitly set it to preserve the .NET 8 visual appearance.
        _statusStrip.RenderMode = ToolStripRenderMode.System;
        Controls.Add(_statusStrip);
    }

    /// <summary>
    /// Shows a dropdown editor, guarding against the .NET 9 breaking change
    /// where DropDownControl(null) now throws ArgumentNullException.
    /// </summary>
    public void ShowDropDown(IWindowsFormsEditorService editorService, Control dropDown)
    {
        if (dropDown is null)
            return;

        editorService.DropDownControl(dropDown);
    }

    // .NET 9: prefer LibraryImport over DllImport for better AOT and trimming support.
    [LibraryImport("user32.dll")]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static partial bool SetForegroundWindow(nint hWnd);

    [LibraryImport("user32.dll", SetLastError = true)]
    private static partial nint FindWindowW(
        [MarshalAs(UnmanagedType.LPWStr)] string? lpClassName,
        [MarshalAs(UnmanagedType.LPWStr)] string? lpWindowName);
}

